Для массы спускающегося груза: $m = m_\text{каретки} + n \cdot m_\text{шайбы} = 267.0 \text{кг}$

\centerline{$\Delta_m = \sqrt{(\Delta_{m_\text{каретки}})^2 + (n \cdot \Delta_{m_\text{шайбы}})^2} = 2.1 \text{кг}, \quad \varepsilon_{m} = \frac{\Delta_m}{m} \cdot 100\% = 0.22\%$.}

Для ускорения: $a=\frac{2h}{t^2} = 0.28552 \text{м}/\text{с}^2$, 

\centerline{$\varepsilon_{a} = \sqrt{(\frac{2}{3} \cdot \frac{\Delta h}{h})^2 + (\frac{\Delta t}{t})^2} \cdot 100\% = 0.08\%, \quad \Delta_a=\frac{a \cdot \varepsilon_a}{100\%} = 2.3 \cdot 10^{-4} \text{м}/\text{с}^2$.}

Для углового ускорения: $\varepsilon=\frac{2a}{d_\text{ступ}} = 12.414 \text{рад}/\text{с}^2$, 

\centerline{$\varepsilon_{\varepsilon} = \sqrt{(\frac{\Delta a}{a})^2 + (\frac{2}{3} \cdot \frac{\Delta d_\text{ступ}}{d_\text{ступ}})^2} \cdot 100\% = 0.08\%, \quad \Delta_\varepsilon=\frac{\varepsilon \cdot \varepsilon_\varepsilon}{100\%} = 0.01 \text{рад}/\text{с}^2$.}

Для момента силы натяжения нити: $M=\frac{md_\text{ступ}}{2}(g-a) = 0.058548 \text{Н}\cdot\text{м}$, 

\centerline{$\varepsilon_M = \sqrt{(\frac{\Delta m}{m})^2 + (\frac{2}{3} \cdot \frac{\Delta d_\text{ступ}}{d_\text{ступ}})^2 + (\frac{\Delta a}{g-a})^2} \cdot 100\% = 0.011\%$,}

\centerline{$\Delta_M=\frac{\varepsilon \cdot \varepsilon_\varepsilon}{100\%} = 7 \cdot 10^{-6} \text{м}/\text{с}^2$.}



\begin{itemize}
    \item Для 1 риски: $M = 0.017+0.0182 \cdot I$.
    \item Для 2 рисок: $M = 0.017+0.0182 \cdot I$.
    \item Для 3 рисок: $M = 0.017+0.0182 \cdot I$.
